INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('DESK-02', 1, 'tech_pattern', NULL, NULL, 'Web・デスクトップ共通', NULL, '{"shortSummary":"Web技術とTauriを組み合わせ、Webアプリの資産をデスクトップアプリにも展開する構成です。","primaryUse":"Webサービスのデスクトップ展開","architectureType":"ハイブリッド構成","primaryLanguage":"TypeScript中心","whatYouCanBuild":"React＋TauriとSupabaseを組み合わせ、既存のWebサービスをPC専用クライアントとしても提供できるデスクトップアプリを構築できます。","whyRecommended":["WebサービスとバックエンドをSupabaseで共有しつつ、デスクトップアプリとしての操作性も提供できるため、PCでの利用頻度が高いユーザー向けの構成に向いています。"],"strengths":["Web版とバックエンドを共有できる","常駐アプリとして使える","軽量に動作する"],"suitableCases":["WebサービスのPC専用クライアントを作りたい","オフライン利用も想定した業務ツール"],"unsuitableCases":["モバイル展開を優先したい場合","Web版だけで十分な場合"],"expectedFeatures":["ログイン・ユーザー管理","データの登録・一覧・編集","リアルタイム更新"]}', 19);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('DESK-03', 1, 'tech_pattern', NULL, NULL, 'Electron業務アプリ', NULL, '{"shortSummary":"Electronで、Node.jsの機能をフル活用した高機能な業務デスクトップアプリを作る構成です。","primaryUse":"高機能業務ツール開発","architectureType":"高機能デスクトップ構成","primaryLanguage":"TypeScript / JavaScript","whatYouCanBuild":"ElectronとNode.jsを使い、ファイル処理・帳票出力・複数ウィンドウ操作など、Web技術だけでは難しい高機能な業務デスクトップアプリを構築できます。","whyRecommended":["Node.jsのAPIをフル活用できるため、ファイルシステムや外部ツールとの連携が多い業務アプリに向いています。"],"strengths":["Node.jsの豊富なライブラリを使える","複数ウィンドウ操作に対応","ファイル・帳票処理が得意"],"suitableCases":["ファイル処理・帳票出力を伴う業務アプリ","複数ウィンドウを持つ管理ツール"],"unsuitableCases":["アプリサイズ・メモリ使用量を最小限にしたい場合","軽量な配布を重視する場合"],"expectedFeatures":["ファイル処理・帳票出力","複数ウィンドウ管理","ローカル認証"]}', 20);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('DESK-04', 1, 'tech_pattern', NULL, NULL, 'Pythonデスクトップ', NULL, '{"shortSummary":"Python（Flet・PySide）で、データ処理にそのまま画面を付けたデスクトップツール構成です。","primaryUse":"社内データ処理ツール開発","architectureType":"軽量デスクトップ構成","primaryLanguage":"Python中心","whatYouCanBuild":"FletやPySideを使い、データ集計・変換ツールや現場向けの簡易操作ツールなど、Pythonの処理にそのまま画面を付けたデスクトップツールを構築できます。","whyRecommended":["Pythonのデータ処理資産をそのまま画面付きツールにできるため、非エンジニアでも扱えるツールを素早く用意したい場合に向いています。"],"strengths":["Pythonの資産をそのまま活用できる","データ処理と相性がよい","短期間で画面を用意できる"],"suitableCases":["データ集計・変換ツールを作りたい","現場向けの簡易操作ツールを作りたい"],"unsuitableCases":["見た目や操作性を重視するアプリ","複数OSへの本格配布が前提の場合"],"expectedFeatures":["データ集計・変換","ファイル入出力","ローカル認証"]}', 21);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('BIZ-01', 1, 'tech_pattern', NULL, NULL, 'React業務システム', NULL, '{"shortSummary":"Reactで操作性の高い画面を構築し、NestJSで業務ロジックを整理する、拡張性の高い業務システム向け構成です。","primaryUse":"業務管理・基幹周辺システム","architectureType":"フロント・API分離型","primaryLanguage":"TypeScript中心","whatYouCanBuild":"React＋NestJSで、顧客管理・案件管理システムや在庫・発注管理システムなど、複雑な業務ロジックと複数の画面を持つ本格的な業務システムを構築できます。","whyRecommended":["React＋Viteにより、操作性の高い業務画面を軽快に構築できます。バックエンドをNestJSで分離することで、業務ロジックや外部サービス連携を整理しやすく、機能追加にも対応しやすい構成になります。","PostgreSQL＋Prismaにより、顧客・案件・商品・注文・履歴など、関係性のある業務データを管理しやすくなります。認証、ファイル管理、監視も周辺技術と組み合わせられるため、開発だけでなく実運用まで見据えた構成にできます。"],"strengths":["TypeScriptを中心に構成を統一しやすい","業務ロジックをAPI側へ整理できる","データ同士の関係を構造的に管理しやすい","機能追加や外部サービス連携に対応しやすい","フロントエンドとバックエンドを分担して開発できる","小規模な初期構築から段階的に拡張できる"],"suitableCases":["顧客・案件・在庫・注文など複数の業務データを扱う","ユーザーごとに権限を分ける必要がある","今後の機能追加や外部連携を想定している","フロントエンドとAPIを分離して保守したい","小規模な初期構築から段階的に拡張したい","社内システムやBtoB向け管理システムを構築したい"],"unsuitableCases":["1〜2画面だけで完結する非常に小さなツール","SEOを最優先するメディア・コンテンツサイト","ネイティブアプリ固有の機能が中心となるサービス","APIを分離する必要がない短期プロトタイプ","サーバーや運用管理をほとんど持ちたくない構成"],"expectedFeatures":["ログイン・ユーザー管理","ロール・権限管理","顧客・案件・商品マスタ","一覧・詳細・登録・編集","検索・絞り込み・並び替え","ファイルアップロード","操作履歴・更新履歴","通知・メール送信","ダッシュボード","CSV・帳票出力","外部API・SaaS連携"]}', 22);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('BIZ-02', 1, 'tech_pattern', NULL, NULL, 'Next.js＋NestJS分離型', NULL, '{"shortSummary":"フロント（Next.js）とバックエンド（NestJS）を分離した、拡張性重視の業務システム構成です。","primaryUse":"業務管理・基幹周辺システム","architectureType":"フロント・API分離型","primaryLanguage":"TypeScript中心","whatYouCanBuild":"フロント（Next.js）とバックエンド（NestJS）を分離した構成で、複数チームが分担開発する業務基盤や、将来的にモバイル版・外部連携も見据えたシステムを構築できます。","whyRecommended":["フロントとAPIを独立してデプロイ・スケールできるため、開発規模が大きくなっても役割分担しやすい構成です。認証もClerkやAuth0など複数の選択肢から選べます。"],"strengths":["フロントとAPIを独立して開発・デプロイできる","チームを分けて分担開発しやすい","モバイル版など将来の展開に対応しやすい"],"suitableCases":["複数チームで分担開発する業務基盤","将来的にモバイル版も見据えたシステム"],"unsuitableCases":["1人〜少人数で完結する小規模開発","フロントとAPIを分ける必要がない小さなツール"],"expectedFeatures":["ログイン・組織管理","一覧・詳細・登録・編集","ファイルアップロード","外部API連携"]}', 23);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('BIZ-03', 1, 'tech_pattern', NULL, NULL, 'Vue＋NestJS業務システム', NULL, '{"shortSummary":"Vue＋NestJSで構築する、Vueに慣れたチーム向けの業務システム構成です。","primaryUse":"業務管理システム","architectureType":"フロント・API分離型","primaryLanguage":"TypeScript中心","whatYouCanBuild":"Vue＋NestJSで、社内管理ツールや業務システムを構築できます。","whyRecommended":["Vueに慣れたチームが、構造化されたバックエンド（NestJS）と組み合わせて業務システムを開発したい場合に適した構成です。"],"strengths":["Vueの知識をそのまま活かせる","業務ロジックをAPI側で整理できる","独自認証も組み込みやすい"],"suitableCases":["Vue採用チームによる業務システム開発","社内管理ツールを作りたい"],"unsuitableCases":["Reactを標準としているチーム","大規模なエンタープライズシステム"],"expectedFeatures":["ログイン・ユーザー管理","一覧・詳細・登録・編集","ファイルアップロード"]}', 24);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('BIZ-04', 1, 'tech_pattern', NULL, NULL, 'Angular企業システム', NULL, '{"shortSummary":"Angularで、大規模かつ統制の取れた企業向け管理システムを構築する構成です。","primaryUse":"大企業の基幹業務システム","architectureType":"フロント・API分離型","primaryLanguage":"TypeScript中心","whatYouCanBuild":"Angular＋NestJSで、大企業の基幹業務システムや、多数の画面を持つ管理コンソールを構築できます。","whyRecommended":["Angularの厳格な設計規約により、大人数のチームで統制のとれた開発がしやすく、長期運用される企業システムに向いています。"],"strengths":["大人数チームでの統制がとれる","長期運用に強い設計規約","Microsoft Entra IDとの連携がしやすい"],"suitableCases":["大企業の基幹業務システムを作りたい","多数の画面を持つ管理コンソールが必要"],"unsuitableCases":["少人数チームでのスピード重視の開発","小規模なツール開発"],"expectedFeatures":["ログイン・権限管理","一覧・詳細・登録・編集","監査ログ","ファイル管理"]}', 25);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('BIZ-05', 1, 'tech_pattern', NULL, NULL, 'Python業務システム', NULL, '{"shortSummary":"React＋FastAPIで、データ処理や分析機能を持つ業務システムを構築する構成です。","primaryUse":"データ活用型の業務システム","architectureType":"フロント・API分離型","primaryLanguage":"Python / TypeScript","whatYouCanBuild":"React＋FastAPIで、データ分析ダッシュボードや、業務自動化を伴う社内システムを構築できます。","whyRecommended":["Pythonのデータ処理・分析ライブラリを業務システムに組み込みやすく、データを扱う業務に強い構成です。"],"strengths":["Pythonのデータ処理資産を活用できる","API処理が高速","AI・自動化機能と連携しやすい"],"suitableCases":["データ分析ダッシュボードを作りたい","業務自動化を伴う社内システムを作りたい"],"unsuitableCases":["Pythonの知見がないチーム","データ処理を伴わない単純なCRUDアプリ"],"expectedFeatures":["データ分析・可視化","一覧・詳細・登録・編集","CSV・帳票出力","バックグラウンド処理"]}', 26);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('BIZ-06', 1, 'tech_pattern', NULL, NULL, 'Microsoft業務基盤', NULL, '{"shortSummary":"Microsoft製品で統一し、既存の社内Microsoft環境と連携する企業向け業務基盤です。","primaryUse":"Microsoft環境と連携する社内システム","architectureType":"Microsoft統合型","primaryLanguage":"C# / .NET","whatYouCanBuild":"Blazor・ASP.NET Core・SQL ServerなどMicrosoft製品で統一し、Microsoft 365と連携する社内システムや、既存の.NET資産を活かす基幹システムを構築できます。","whyRecommended":["社内のMicrosoft環境（Active Directory、SQL Server等）とそのまま連携できるため、既存インフラを活かしたい企業に向いています。"],"strengths":["既存のMicrosoft環境と連携しやすい",".NET資産を活用できる","Entra IDでシングルサインオンできる"],"suitableCases":["Microsoft 365と連携する社内システムを作りたい","既存の.NET資産を活かしたい"],"unsuitableCases":["非Microsoft環境が前提のチーム","オープンソース中心の技術選定をしたい場合"],"expectedFeatures":["シングルサインオン","一覧・詳細・登録・編集","ファイル管理","帳票出力"]}', 27);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('AI-01', 1, 'tech_pattern', NULL, NULL, '最速AI Webアプリ', NULL, '{"shortSummary":"Next.jsとAI APIを組み合わせ、AI機能を持つWebアプリを最短で作れる構成です。","primaryUse":"AI機能付きWebアプリの構築","architectureType":"AI Web構成","primaryLanguage":"TypeScript中心","whatYouCanBuild":"Next.jsとOpenAI・Claude・GeminiのAPIを組み合わせ、AIチャットサービスや文章生成・要約ツールを最短で構築できます。","whyRecommended":["フロントとAI呼び出しを同じNext.jsプロジェクトに統合できるため、専用のAIサーバーを用意せずにAI機能付きWebアプリを素早く公開できます。"],"strengths":["AI機能を最短距離で組み込める","フロントとAPIが一体で開発しやすい","複数のAIモデルを選べる"],"suitableCases":["AIチャットサービスを作りたい","文章生成・要約ツールを作りたい"],"unsuitableCases":["複数ステップの高度な自動判断が必要","大規模な文書検索基盤が必要"],"expectedFeatures":["AIチャット応答","文章生成・要約","ログイン・ユーザー管理"]}', 28);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('AI-02', 1, 'tech_pattern', NULL, NULL, '標準AIエージェント', NULL, '{"shortSummary":"LangGraphなどで、複数ステップの判断を行うAIエージェントを構築する標準構成です。","primaryUse":"AIエージェントの構築","architectureType":"AIエージェント構成","primaryLanguage":"Python中心","whatYouCanBuild":"FastAPI・LangGraph・pgvectorを組み合わせ、複数ステップで判断しながら動く業務判断の自動化AIエージェントや、複数ツールを操作するAIアシスタントを構築できます。","whyRecommended":["LangGraphによる状態管理で、単純な一問一答を超えた複雑な処理フローを整理しやすく、実運用に耐えるAIエージェントの標準構成として使えます。"],"strengths":["複数ステップの処理を整理できる","ベクトル検索と組み合わせやすい","監視まで含めた運用設計がしやすい"],"suitableCases":["業務判断を自動化するAIエージェントを作りたい","複数ツールを操作するAIアシスタントを作りたい"],"unsuitableCases":["単純な一問一答チャットで十分な場合","TypeScriptに統一したい場合"],"expectedFeatures":["AIエージェントの状態管理","ツール呼び出し","文書検索","処理履歴の確認"]}', 29);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('AI-03', 1, 'tech_pattern', NULL, NULL, 'TypeScript統一AI SaaS', NULL, '{"shortSummary":"フロントからバックエンドまでTypeScriptで統一したAI SaaSの構成です。","primaryUse":"AI機能付きSaaSの構築","architectureType":"TypeScript統一構成","primaryLanguage":"TypeScript中心","whatYouCanBuild":"Next.js・NestJS・LangChain.jsなどTypeScriptで統一し、AI機能付きの業務SaaSやAIチャット組み込み型サービスを構築できます。","whyRecommended":["フロントからバックエンド、AI連携まで単一言語（TypeScript）で開発できるため、型の恩恵を受けながらチーム全体の学習コストを抑えられます。"],"strengths":["言語をTypeScriptに統一できる","型安全にAI連携を実装できる","フロント〜APIまで一貫した開発体制"],"suitableCases":["AI機能付きの業務SaaSを作りたい","AIチャット組み込み型サービスを作りたい"],"unsuitableCases":["Pythonの機械学習資産を多用したい場合","高度なベクトル検索基盤が必要な場合"],"expectedFeatures":["AIチャット応答","ログイン・組織管理","データの登録・一覧・編集"]}', 30);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('AI-04', 1, 'tech_pattern', NULL, NULL, '文書問い合わせRAG', NULL, '{"shortSummary":"検索と生成を組み合わせ、根拠を示しながらAIが回答するRAG構成です。","primaryUse":"文書検索・問い合わせAI","architectureType":"RAG構成","primaryLanguage":"Python中心","whatYouCanBuild":"FastAPI・pgvector・RAG構成を組み合わせ、社内マニュアル問い合わせボットや、契約書・規定を検索して根拠付きで回答するAI検索システムを構築できます。","whyRecommended":["検索（Retrieval）と生成（Generation）を組み合わせることで、AIの回答に根拠となる文書を示せるため、正確性が求められる社内文書検索に向いています。"],"strengths":["回答に根拠文書を示せる","社内文書をそのまま活用できる","既存のPostgreSQLを拡張して使える"],"suitableCases":["社内マニュアル問い合わせボットを作りたい","契約書・規定の検索AIを作りたい"],"unsuitableCases":["文書検索を伴わない単純なチャット","検索対象の文書が極めて少ない場合"],"expectedFeatures":["文書検索・根拠提示","AIチャット応答","ファイルアップロード"]}', 31);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('AI-05', 1, 'tech_pattern', NULL, NULL, '自動化・業務連携AI', NULL, '{"shortSummary":"n8nと外部SaaS連携を組み合わせ、業務フローを自動化する構成です。","primaryUse":"業務自動化・SaaS連携","architectureType":"ワークフロー自動化構成","primaryLanguage":"ノーコード中心","whatYouCanBuild":"n8nとOAuth連携を組み合わせ、メールやスプレッドシート、チャットツールをつないだ問い合わせ対応の自動振り分けなど、業務自動化の仕組みを構築できます。","whyRecommended":["ノーコード・ローコードのワークフローツールを使うため、エンジニアでなくても自動化フローを組み立てやすい構成です。"],"strengths":["ノーコードでフローを組める","外部SaaSとの連携が豊富","開発コストを抑えられる"],"suitableCases":["メール・スプレッドシート連携を自動化したい","問い合わせ対応を自動振り分けしたい"],"unsuitableCases":["複雑な条件分岐を伴う独自ロジックが中心","画面を伴う本格的なアプリが必要な場合"],"expectedFeatures":["外部SaaS連携","自動振り分け・自動通知","定型業務の自動実行"]}', 32);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('AI-06', 1, 'tech_pattern', NULL, NULL, '高信頼AI基盤', NULL, '{"shortSummary":"高度なベクトル検索・監視を備えた、信頼性重視のAI基盤構成です。","primaryUse":"エンタープライズAI基盤","architectureType":"高信頼AI基盤構成","primaryLanguage":"Python中心","whatYouCanBuild":"FastAPI・Pinecone/Weaviate・Auth0・Sentryなどを組み合わせ、エンタープライズ向けAI検索基盤や、高精度・高可用性が求められる社内AIシステムを構築できます。","whyRecommended":["専用のベクトル検索基盤や監視・認証サービスを組み合わせることで、大規模利用や高い信頼性が求められる場面に耐える構成になっています。"],"strengths":["大規模なベクトル検索に対応できる","監視・認証が最初から組み込まれている","企業利用に耐える信頼性"],"suitableCases":["エンタープライズ向けAI検索基盤を作りたい","高精度が求められる社内AIシステムを作りたい"],"unsuitableCases":["小規模な検証段階のAI機能","コストを最小限に抑えたい場合"],"expectedFeatures":["大規模文書検索","AIエージェントの状態管理","監視・アラート","シングルサインオン"]}', 33);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('INF-01', 1, 'tech_pattern', NULL, NULL, '低価格セルフホスト', NULL, '{"shortSummary":"Docker ComposeとCaddyで、低コストに自社サーバー上でシステムを運用する構成です。","primaryUse":"低コストな自社運用基盤","architectureType":"セルフホスト構成","primaryLanguage":"技術非依存","whatYouCanBuild":"Docker ComposeとCaddyを使い、予算の限られた小規模システムの運用や、社内実験環境を、自社サーバー上に低コストで構築できます。","whyRecommended":["1台のサーバーにアプリ・DB・ストレージをまとめて配置できるため、クラウドの従量課金を避けて固定費で運用したい場合に向いています。"],"strengths":["固定費で運用できる","1台で完結する構成","HTTPS化が簡単"],"suitableCases":["予算の限られた小規模システムの運用","社内実験環境の構築"],"unsuitableCases":["大規模なアクセスに対応したい場合","高可用性が必須の本番システム"],"expectedFeatures":["アプリ・DB・ストレージの一括運用","HTTPS化","認証基盤の自社運用"]}', 34);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('INF-02', 1, 'tech_pattern', NULL, NULL, 'AWSサーバーレス', NULL, '{"shortSummary":"AWSのサーバーレスサービスで構築する、利用量に応じて自動でスケールする構成です。","primaryUse":"スケーラブルなAPI基盤","architectureType":"サーバーレス構成","primaryLanguage":"技術非依存","whatYouCanBuild":"AWS Lambda・DynamoDB・Amazon S3・CloudFrontを組み合わせ、アクセス量が変動するAPIや、AWSに統一したいシステム基盤を構築できます。","whyRecommended":["利用量に応じて自動でスケールし使った分だけ課金されるため、アクセス数の予測が難しいサービスでもコストを最適化しやすい構成です。"],"strengths":["自動でスケールする","使った分だけ課金される","AWSの各種サービスと連携しやすい"],"suitableCases":["アクセス量が変動するAPIを運用したい","AWSに統一したいシステム基盤"],"unsuitableCases":["常時接続が必要な処理が中心","AWS以外のクラウドに統一したい場合"],"expectedFeatures":["自動スケーリング","CDN配信","ユーザー認証・権限管理"]}', 35);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('INF-03', 1, 'tech_pattern', NULL, NULL, 'Google Cloud統一', NULL, '{"shortSummary":"Google Cloud・Firebaseで統一した、モバイル・Web共通のインフラ構成です。","primaryUse":"Google Cloud統一基盤","architectureType":"クラウド統一構成","primaryLanguage":"技術非依存","whatYouCanBuild":"Flutter・Firestore・Cloud Functions・Cloud Runを組み合わせ、Googleサービスに寄せたシステム基盤や、モバイルとWebを一体運用するサービスを構築できます。","whyRecommended":["モバイル・Web・バックエンドをGoogle Cloud/Firebaseで統一することで、サービス間の認証・データ連携がシンプルになります。"],"strengths":["モバイル・Webを一体運用できる","認証・データ連携がシンプル","AI機能（Gemini）とも統合しやすい"],"suitableCases":["Googleサービスに寄せたシステム基盤を作りたい","モバイルとWebを一体運用したい"],"unsuitableCases":["他クラウドとのマルチクラウド構成にしたい場合","リレーショナルデータを重視する場合"],"expectedFeatures":["クロスプラットフォーム認証","リアルタイムデータ同期","コンテナ実行基盤"]}', 36);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('INF-04', 1, 'tech_pattern', NULL, NULL, 'Azure企業基盤', NULL, '{"shortSummary":"Azureで統一した、企業のMicrosoft環境と連携するインフラ構成です。","primaryUse":"企業向けAzure基盤","architectureType":"クラウド統一構成","primaryLanguage":"技術非依存","whatYouCanBuild":"Angular・Azure Functions・Azure SQL・Azure App Serviceを組み合わせ、社内ADと連携するシステム基盤や、Azure中心の企業システム運用を構築できます。","whyRecommended":["Microsoft Entra IDなど既存のAzure環境とそのまま連携できるため、Microsoft製品を導入済みの企業のシステム基盤に向いています。"],"strengths":["既存のAzure環境と連携しやすい","シングルサインオンに対応","企業向けサポート体制がある"],"suitableCases":["社内ADと連携するシステム基盤が必要","Azure中心の企業システムを運用したい"],"unsuitableCases":["非Microsoft環境が前提のチーム","小規模な個人開発"],"expectedFeatures":["シングルサインオン","サーバーレス処理","リレーショナルDB運用"]}', 37);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('INF-05', 1, 'tech_pattern', NULL, NULL, 'Kubernetes大規模基盤', NULL, '{"shortSummary":"Kubernetesで、大規模かつ高可用性が求められるシステムを運用する構成です。","primaryUse":"大規模システムの運用基盤","architectureType":"大規模分散構成","primaryLanguage":"技術非依存","whatYouCanBuild":"NestJS・FastAPI・PostgreSQL・Redis・Kubernetesを組み合わせ、アクセス量の大きいサービス基盤や、複数サービスを統合運用する大規模システムを構築できます。","whyRecommended":["Kubernetesによる自動配置・スケール・障害復旧により、高可用性が求められる大規模運用に耐える構成です。"],"strengths":["高可用性を実現できる","複数サービスを統合運用できる","自動スケール・自動復旧に対応"],"suitableCases":["アクセス量の大きいサービス基盤を運用したい","複数サービスを統合運用したい"],"unsuitableCases":["小〜中規模で運用コストを抑えたい場合","運用チームの体制が薄い場合"],"expectedFeatures":["自動スケーリング","障害自動復旧","大規模検索基盤との連携"]}', 38);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('INF-06', 1, 'tech_pattern', NULL, NULL, 'オンプレミス構成', NULL, '{"shortSummary":"外部クラウドを使わず、社内設備でシステムを運用する構成です。","primaryUse":"オンプレミス業務基盤","architectureType":"オンプレミス構成","primaryLanguage":"C# / .NET","whatYouCanBuild":"ASP.NET Core・SQL Server・MinIO・オンプレミスサーバーを組み合わせ、データを外部に出せない業界のシステムや、既存の社内インフラを活かしたシステムを構築できます。","whyRecommended":["外部クラウドを一切使わずに構築できるため、データの持ち出しに厳しい規制がある業界や、既存の社内設備を活用したい場合に適しています。"],"strengths":["データを外部に出さずに運用できる","既存の社内設備を活用できる","S3互換のファイル保存も自社運用できる"],"suitableCases":["データを外部に出せない業界のシステム","既存の社内インフラを活かしたい"],"unsuitableCases":["クラウドの自動スケールを活用したい場合","運用要員を最小限にしたい場合"],"expectedFeatures":["独自認証・アクセス制御","ファイル管理","既存システムとの連携"]}', 39);
INSERT INTO registry_stack_presets (id, release_id, preset_type, preset_kind, parent_pattern_id, name, app_type_ids, details_json, sort_order) VALUES ('INF-07', 1, 'tech_pattern', NULL, NULL, 'Cloudflareエッジ基盤', NULL, '{"shortSummary":"Cloudflare Workersを中心に、世界各地のエッジで低遅延に動くインフラ構成です。","primaryUse":"グローバル配信基盤","architectureType":"エッジ構成","primaryLanguage":"TypeScript中心","whatYouCanBuild":"Cloudflare Workersを中心に、グローバルに配信するAPIやWebアプリ、低遅延が求められるエッジ処理を構築できます。","whyRecommended":["世界各地のエッジで処理が実行されるため、海外を含む幅広い地域のユーザーに低遅延でサービスを提供したい場合に向いています。"],"strengths":["世界中に低遅延で配信できる","サーバー管理がほぼ不要","スケールを意識せず開発できる"],"suitableCases":["グローバル配信するAPI・Webアプリを作りたい","低遅延が求められるエッジ処理が必要"],"unsuitableCases":["長時間の重い処理が中心の場合","特定リージョンのみで完結するシステム"],"expectedFeatures":["エッジAPI処理","キャッシュ制御","認証前処理"]}', 40);
